use super::{copyin, copyout, writable, poll_fd, now_ns, park_poll};

pub fn call(a: &[usize]) -> isize {
    if a.len() < 5 {
        return -22;
    }
    if a[3] != 0 {
        return -38;
    }
    let nfds = a[1];
    if nfds > 16 {
        return -22;
    }
    let deadline = if a[2] == 0 {
        None
    } else {
        let mut t = [0u8; 16];
        if copyin(a[2], &mut t).is_err() {
            return -14;
        }
        let sec = i64::from_le_bytes([t[0], t[1], t[2], t[3], t[4], t[5], t[6], t[7]]);
        let nsec = i64::from_le_bytes([t[8], t[9], t[10], t[11], t[12], t[13], t[14], t[15]]);
        if sec < 0 || nsec < 0 || nsec >= 1_000_000_000 {
            return -22;
        }
        let duration = (sec as u64).saturating_mul(1_000_000_000).saturating_add(nsec as u64);
        Some(now_ns().saturating_add(duration))
    };
    let len = nfds * 8;
    let mut bytes = [0u8; 128];
    if len != 0 {
        if a[0] == 0 || a[0].checked_add(len).is_none() {
            return -14;
        }
        if copyin(a[0], &mut bytes[..len]).is_err() || !writable(a[0], len) {
            return -14;
        }
    }
    loop {
        let mut ready = 0isize;
        let mut input = false;
        for i in 0..nfds {
            let p = i * 8;
            let fd = i32::from_le_bytes([bytes[p], bytes[p + 1], bytes[p + 2], bytes[p + 3]]);
            let events = i16::from_le_bytes([bytes[p + 4], bytes[p + 5]]);
            let revents = if fd < 0 { 0 } else { poll_fd(fd, events) };
            if fd == 0 {
                input = true;
            }
            let encoded = revents.to_le_bytes();
            bytes[p + 6] = encoded[0];
            bytes[p + 7] = encoded[1];
            if revents != 0 {
                ready += 1;
            }
        }
        let expired = match deadline {
            Some(end) => now_ns() >= end,
            None => false,
        };
        if ready != 0 || expired {
            if len != 0 && copyout(a[0], &bytes[..len]).is_err() {
                return -14;
            }
            return ready;
        }
        park_poll(deadline, input);
    }
}
